 $item=$t['clauses']['_package'];$v=array_fill_keys($item['fields'],'Согласованное условие вымышленного заказа');
 $v=array_replace($v,['owner.full_name'=>'Образец Исполнитель Иванович','owner.inn'=>'000000000000','owner.bank'=>'Вымышленный банк','owner.account'=>'00000000000000000000','owner.bank_details'=>'Образец — не платёжные реквизиты','owner.email'=>'owner@example.invalid','owner.contact'=>'owner@example.invalid','owner.postal_address_line'=>'','client.type'=>'Физическое лицо','client.registration'=>'','client.bank_details'=>'','client.authority'=>'Действует лично','client.name'=>'Образец Заказчица Петровна','client.legal_description'=>'Образец Заказчица Петровна, действует лично','client.signatory'=>'Образец Заказчица Петровна','client.email'=>'client@example.invalid','client.contact'=>'client@example.invalid','client.authorized_contact'=>'client@example.invalid','contract.number'=>'ОБРАЗЕЦ-2026','contract.city'=>'Романово','contract.date'=>'2026-11-02','spec.date'=>'2026-11-02','spec.version'=>'2 — образец','project.name'=>'Демонстрационный сайт мастерской','project.purpose'=>'Приём обращений о ремонте','project.type'=>'Сайт','project.audience'=>'Совершеннолетние посетители мастерской','price.total'=>'12000.00','price.words'=>'Двенадцать тысяч рублей','price.rights_fee'=>'2000.00','acceptance.business_days'=>'5','support.start_event'=>'Подписанная передача результата','support.duration'=>'30 календарных дней','support.end_calculation'=>'Со следующего дня после подтверждённой передачи, 30 календарных дней','support.end_date'=>'Определяется по подтверждённой дате передачи','support.scope'=>'Консультации по переданным функциям и проверка замечаний','support.response_time'=>'В течение 2 рабочих дней','support.defect_procedure'=>'Воспроизведение по версии и сценарию, согласование срока исправления с учётом сложности; подтверждённые дефекты не расходуют творческие правки','support.contacts'=>'owner@example.invalid','spec.completion_deadline'=>'2026-12-01','spec.milestones'=>json_encode([['result'=>'Форма обращения и страница услуг','start_on'=>'2026-11-03','due_on'=>'2026-12